import json

with open('data/modern-translation/t1251_part3.json', 'r', encoding='utf-8') as f:
    modern = json.load(f)

# 段101
modern[101] = "【持法戒行功德】應當獨自在淨室中，燒香供養三寶行法，觀想一切貧窮的人都得到寶物，對於一切有情生起慈悲心念，不要生起瞋恚、誑諂、害他的心。如果起了少許瞋心，就會失去大神驗，要常守護自心不要起瞋恚。如果持這個咒法的人，每天要憶念我以及我的男女眷屬、讚歎我們，恆常以十善業相助。【义解】本段講成就驗相出現後，行者應當持守的戒行：獨處淨室、燒香供養、慈悲濟貧、不起瞋恚、常念本尊與眷屬、行十善，是維持法驗的關鍵。"
# 段102
modern[102] = "【諸天擁護利益】那些天眾的福力增長光明，普遍令眾生證得無上菩提。而那些天眾見到這件事之後，都大生歡喜，一起來擁護行者。持咒的人又能壽命長遠，經無量歲，永遠脫離三惡道的痛苦，沒有災難橫死。又能得到如意寶珠以及地下伏藏，神通自在，所有願望都能成就。如果求官職榮位沒有不成就的，也能解一切禽獸的語言。【义解】本段講如法持戒行法的廣大利益：諸天歡喜擁護，長壽、離惡道、無橫災、得寶藏、神通自在、滿願、得官、解禽獸語，和前面如意寶珠法的功德一致，再次強調。"
# 段103
modern[103] = "【曼荼羅供養畢】種子曼荼羅的供養法已經說完了。」「接著又應當講解種子曼陀羅的法印。」「示現三動惡魔三天身梵字根本真言說：「唵毘地瑟陀𭇎㗭者沙𭇎」「延命梵本真言說。「唵梵毘地瑟秫陀娑𭇎」「悲生梵本真言說：「唵梵毘地瑟地𭇎㗭地𭇎㗭沙𭇎」【义解】本段總結種子（因）曼荼羅供養法完畢，引出梵字（種子字）法門，分別給出降魔（三動惡魔）、延命、慈悲（悲生）三種梵本根本真言。"
# 段104
modern[104] = "【梵字為佛法根本】那時大日薄伽梵說：「未來世的眾生想要早點成就悉地，首先要從阿闍梨處領受梵字（種子字）。雖然修行其他法門，但不知道這個法，悉地就很難成就。為什麼呢？這是三世諸佛的肝心，是釋迦牟尼如來的兩隻眼睛，是一切聖人的命脈，是多聞王的福德藏，是一切眾生的依報。【义解】本段由大日如來開示梵字種子法的重要性：是三世諸佛心髓、釋迦佛眼、聖人命脈、多聞天王福德藏、眾生依止的根本，不從阿闍梨領受梵字，修一切法都難以成就。"
# 段105
modern[105] = "【謗法重罪警示】如果有眾生不知道三世諸佛的肝心，怎麼能成就佛道？如果有眾生矇住釋迦的眼睛，怎麼能得到釋迦的護佑？如果有眾生斷一切聖人的命脈、毀滅福德藏、矇住諸尊的眼睛，將來怎麼能出離地獄？怎麼能得到福德？怎麼能得到智慧的因？想要早點成就世間、出世間的願望，應當受持梵本真言梵字，因為這是三世諸佛的肝心。【义解】本段從反面警示：不持梵字就是壞佛眼、斷聖人命、滅福德藏，必墮惡道，無法成佛；正面勸導行者必須受持梵字真言，才能快速滿足世出世間願望。"
# 段106
modern[106] = "【梵字偈頌根本】令一切眾生受持這三種梵本真言，三合共二十八個字。行者應當體悟梵字的本意。偈說：「諸眾生身，與一佛身，是故諸佛，以此大願，說法時為，根本種子。」「延命偈說：「三世諸佛，以不殺戒，是故是教。有智行者，來世眾生，可傳是戒。【义解】本段說明三種梵本真言共三合二十八字，行者需理解其義；隨後給出三個核心偈頌：第一（根本種子偈）說明生佛不二，梵字是諸佛度生的根本種子；第二延命偈以不殺戒為延命根本。"
# 段107
modern[107] = "【三聚淨戒梵偈】」「悲生偈說：「一切諸佛，諸眾生等，與忍施法，當此教人，可行是心。」「這些偈頌就是梵本真言的心中心，乃至三聚淨戒也是如此，因此行者要以這些偈的義理作為觀智的根本。這個偈的功德就算窮盡劫數也說不完，這個偈橫豎有無限意義，隨行者的發心都會吉祥。【义解】本段給出第三個悲生偈（布施、忍辱、慈悲度生），說明這三偈就是梵字真言的核心，對應三聚淨戒（攝律儀、攝善法、饒益有情），功德無量，是觀行的根本。"
# 段108
modern[108] = "【觀音開示持法】」觀世音菩薩說：「你隨順眾生的根機，應當為他們說法。如果有未來世的眾生修多聞迦野王法的，就是延續佛法的壽命。如果不持這個法，就是斷佛法僧三寶的壽命。想要受持這個法的人，每天清晨合掌一心誦母明一千遍，就能滅除無始生死以來的無量重罪，生生世世常遇諸佛出世，因為罪業消滅的緣故。【义解】本段由觀世音菩薩開示：受持本法就是續佛慧命，不持就是斷三寶命脈；並講受持方法：每日清晨專心持母明千遍，能滅無量重罪，生生常值諸佛。"
# 段109
modern[109] = "【根本大陀羅尼】就算本來應當墮入六道，依靠這個功德也不會墮入六道，而是為了度化他人示現變化在六道中。受持一遍功德尚且這麼多，何況曉夜三時一心精進呢。如果修行這個法，首先應當把根本大咒誦十萬遍。首先多聞迦陀野根本大陀羅尼說：「曩謨三滿多菩馱南（一）　阿他佉嚕菩怛羅耶（三）【义解】本段講持法功德：不但不墮惡道，還能自在化身六道度化眾生，勸勉行者晝夜三時精進；要求修法前先持根本大陀羅尼十萬遍作為基礎，隨後引出根本大咒。"
# 段110
modern[110] = "【根本陀羅尼續】毘舍那藥叉吠賒羅跋那闍耶（四）　麼迦瞿羅闍耶（五）　夜叉地婆哩婆麼哩耶（六）　薩都哩耶婆賒耶（七）　鉢囉婆訶娜耶（八）　喜摩泮鉢囉娑耶（九）　唵（十）多娑抳始曬毘娑羅麼娜耶（十一）　麼賀（引）曷囉闍耶（十二）【义解】本段是根本大陀羅尼咒的中間部分，梵文密咒原字照錄，是整部儀軌最核心的根本咒，持十萬遍即得法的基礎相應。"
# 段111
modern[111] = "【根本大咒圓滿】「佉唎羯伽哆囉耶（十三）　唵唓都耶（十四）唵摩唓都（十五）　娑嚩賀（引）」曉夜三時之中，每時誦一千遍，或者二十一遍，同時念誦母忿怒真言等。行者必須從已經得灌頂的阿闍梨處受得法印，也就是得到灌頂位。想要受法，先要勤修精進，見到好相，也可以測驗神驗。【义解】本段圓滿根本大陀羅尼咒，講日常持誦的數量（每時千遍或二十一遍，兼持忿怒母咒）；強調求法必須從已得灌頂的合格阿闍梨處受法、得灌頂，精進修行到見好相、有靈驗才能正式受法。"
# 段112
modern[112] = "【灌頂傳法規範】如果沒有好相，就要更加懺悔直到得到好相。得到神驗之後，再受法。如果沒有經過灌頂，受法也沒有功德。如果跟隨阿闍梨得到受法，就是得到灌頂位；如果得不到印信（傳法印可），就得不到灌頂位。這些因緣不具足，就不能傳授給他人。如果沒有得到灌頂位，就不能稱為阿闍梨。只以自己心意作為本曼陀羅，如果和這個果位、階位、業行、心意不相似，真言行人作為佛子行事，就會滅失大神驗，這難得的密印真言在現世就會全部滅盡。【义解】本段詳細規範傳法灌頂的要求：不見好相需懺悔，不灌頂受法無功，必須得阿闍梨印可才是合格接法者，否則法驗盡失，強調密法傳承的嚴肅性。"
# 段113
modern[113] = "【擇期修法規範】而後行者得到這些意趣受法、傳法，如果有受法弟子前來，要觀察他的心意、行為、心相、威儀。想要成就世間、出世間悉地，隨著願望製作方、圓等形狀的壇，陳設各種供具作法，以三日、五日、七日、九日、十四日、二十一日、三十日、九十日、百日為一期，不要在污穢的地方修法。【义解】本段講傳法時要擇器（觀察弟子根器威儀），以及不同悉地的修法時限（3/5/7/9/14/21/30/90/100日為一期），修法必須遠離穢處。"
# 段114
modern[114] = "【修法方位與金剛橛】在閑靜的地方如法念誦，不要生起攀緣心。如果生起攀緣，就從當下境界起觀行。息災法的本尊曼陀羅面向西南，行者面向東北。降伏法本尊面向東北，行人面向西南，可以蹲踞或者結跏趺坐。敬愛等各種行法，和息災法一樣做。如果想要修法，首先應當製作金剛橛，形狀像獨鈷杵，頭部像矛、末端是杵形，先用大界加持、金剛橛真言等加持，用金剛木等材料製作。【义解】本段講修法的處所（閑靜處）、用心（不攀緣，緣起即觀）；不同事業的方位：息災尊向西南、行者向東北，降伏尊向東北、行者向西南，敬愛同息災；以及修法結界用的金剛橛的形制、材料、加持方法。"
# 段115
modern[115] = "【金剛誓語偈】真言行者以至信心作法結印，又講說摩訶多聞王心中的大極密語，行者應當受持這個偈句：「假使日月從空中墜落到地上，或者大地傾覆，就算發生這樣的事，持明者這個法也必定成就，不應生起少許懷疑；除了瞋恚心的行人，這個法很容易成就。不須假借持戒，（自然）能利益貧窮人，一切人都恭敬，直到壽命終盡。【义解】本段講行者要以信心結印，受持多聞天王的金剛誓語偈：縱使日月墮、大地壞，本法也必定成就，只要斷除瞋恚，不須苦行持戒就能成辦，利益貧窮、受人恭敬。"
# 段116
modern[116] = "【天王守護誓願】加陀王的加持，能遠離各種厄難，藥叉大將都會護持，跟隨受持的人。如果能受持這個法，一切法都能成就，迅速如箭射出；諸王都會恭敬這個人，所求都能成辦，必定得到無盡寶藏。千俱胝數的夜叉，都守護持明者，能滿足各種大願，解脫一切惡趣。」「也就是梵本真言明說：【义解】本段繼續天王的守護誓願：本尊加持離難，藥叉護持，法成就神速，國王恭敬，得無盡寶，千億夜叉守護，滿願解脫惡趣；隨後引出梵本真言。"
# 段117
modern[117] = "【梵本真言被甲】「曩謨三滿多（一）　縛日羅（二合）赦唵（三）　阿婆羅耶（四）婆哆般捨儞耶（五）　陀娑𭇎（六）　唵跋折羅（二合）婆儞多毘使者（七）　娑縛迦（引）」「行者應當以這個真言灑自己的身體肢分，首先作寶印，二手合掌放在頂上，令真言遍滿所有支分。【义解】本段給出梵本被甲真言，說明用法：誦真言灑淨全身，先結寶印在頂上，令真言加持遍滿全身，得到守護。"
# 段118
modern[118] = "【被甲與七光觀】最初誦這二十八個字，那二十八字真言，就成為我身上的瓔珞。接著應當結天王梵本密語被甲印，也就是結金剛合掌放在心上，觀想這個行人身上被著甲冑的形相。完全理解那個偈的意思，使用這個梵本明。如果想要證得無生法忍，就觀想七個真言梵字的光明。自己閉上眼睛念，有一金輪環繞顯現七種光明：【义解】本段講被甲印的用法：誦二十八字真言為身莊嚴瓔珞，結金剛合掌當心，觀自身披金剛甲冑；接著講求無生忍的光明觀：觀七梵字現七種光明，金輪圍繞。"
# 段119
modern[119] = "【七種光明觀想】第一種青色如青琉璃、第二黃色如沙金、第三赤色如火燒塊、第四白色如銀子、第五紅色如頗梨（玻璃）、第六青黃色混合如瑪瑙、第七青白色混合如車磲。這樣的光明從自己口中出來，進入本尊口中，又再出來進入自己的頂中。這樣的光明相續不斷，在一切眾生身中出入，就閉上眼口誦三部母真言等七種真言：【义解】本段詳細描述七種光明的顏色與質地：青、黃、赤、白、紅、青黃瑪瑙、青白車磲；以及光明的流動路徑：自口出→入本尊口→出→入自頂→出入一切眾生身，是自他不二的光明相應觀；隨後說明要誦七種真言。"
# 段120
modern[120] = "【七種光明真言】一、󱁬字；二、𬿘字；三、二十八字真言；四、天王梵本明妃；五、大禁縛偈明；六、如意寶珠明；七、供養會真言等，這名叫七種光明真言。行者體悟這個意思，就能明了成就觀智。梵字的形相已經說完了。」「接著說護摩扇底迦法（息災）、𮑱瑟徵迦法（增益）、阿毘遮盧法（降伏）相應的事。【义解】本段列出七種光明真言的內容：三部母字、二十八字梵本、天王明妃、禁縛偈、如意寶珠明、供養真言，共七種，配七種光明；說明通達這個觀行就成就觀智；結束梵字法部分，引出三種護摩事業法。"
# 段121
modern[121] = "【護摩前行囑累】行者應當至心聽聞這個大密相應大法，聽到之後就要信受奉行。」「修習真言行的人，應當至心如法清淨奉持，不要生起一切非法的惡意行事。如果有一切眾生想要修護摩法，首先應當結鎮護自身的印法：左右手的地、水、火指在內相縛，風指豎起指尖合作寶形，二空指（大拇指）並列橫放在嘴上。【义解】本段囑咐行者要至心信受護摩密法，清淨持戒，不起惡念；講護摩前的鎮護自身印的結法：地水火內縛，風指作寶形，空指橫放口邊，是護摩前的防護。"
# 段122
modern[122] = "【護身印與行道】觀想這就是一切世間諸聖眾的一一護身印明，我全都被著，用這個印印五處。明說：「曩謨三滿多縛日羅（二合）赦（一）　鉢荼羅吠（二）　藥娑多（三）　娑嚩賀（引）」「如果進入道場想要做護摩，首先要行道。首先行者應當拿一把刀鐮，結道場作法印。【义解】本段講鎮護印的觀想（一切聖眾護身印被身）、用法（印五處）與對應真言；進入護摩道場首先要行道，手持刀鐮，結道場印。"
# 段123
modern[123] = "【行道刀印法】右手取刀，左手叉腰，橫向行步。那時睜開忿怒眼，發出忿怒的長聲，就誦彼明、彼母部二字真言。在三種修法中，或者用右手作刀印觀想大刀。明說：「󱃳𮥟」「接著是天王一脚三眼印。左右手作刀印，如果用大刀就用實物，若用小刀就用印，從心到牙左右交替比劃。【义解】本段講護摩行道的方法：右手持刀、左手叉腰、橫步行走、忿怒眼發忿怒聲、誦母部二字真言；或作刀印觀想大刀，真言為佛部母二字；隨後引出天王一脚三眼印的用法。"
# 段124
modern[124] = "【踏鬼座法】首先在本座的位置觀想大鬼神的形狀，如果沒有就觀想所有鬼形，放在入堂道的位置。結咒印法，生起忿怒的觀想。從那個鬼形上踏過去，然後把它取來放在草座下面，如果是座具等下面也可以，自己坐在它上面行法。然後就座，把刀放在胸口上，誦根本咒二十一遍。接著結界阿闍梨身印：左右手握拳，地指（小指）橫臥，二水指（無名指）交叉伏下，印五處。【义解】本段講護摩降伏法的踏鬼觀行：觀鬼形在道上，踏過後放在座下，坐其上以表降伏；入座後刀放胸前，誦根本咒21遍；隨後結阿闍梨身印結界，印五處。"
# 段125
modern[125] = "【諸結界印明】真言說：「唵誐誐嚩𫄅吽（二合引入）」「接著是大壇法印。左右手作拳，二大拇指交叉橫臥，在壇中遍佈加持。明說：「唵誐𧿇（二合）（一）　𧿇野𫄅吽（引入）」「接著是大壇結印。左右手作拳，風指（食指）交叉伏下，放在壇上。明妃說：【义解】本段依次給出阿闍梨身印真言、大壇遍加持印（拳、大指交叉臥）與真言、大壇結界印（拳、風指交叉伏），逐層加持壇場結界。"
# 段126
modern[126] = "【上下方結界印】「唵誐野（一）　弟娑吽（二）　索縛賀（引）」「接著是四方、上方、下方結印。左右手作拳，空指（大拇指）指尖合在一起。明說：「唵弟誐（二合引）陀（一）　吽（二）　增婆𭇎」「接著是大智大印。左右二手合掌，十指分開豎立拍打，觀想火天王打碎一切不祥魔惡事。【义解】本段給出大壇結印真言，隨後講四方上下（六合）結界印（握拳、拇指合）與真言；再講大智印（合掌十指開立拍擊），觀想火天碎魔，是遣除魔障的印。"
# 段127
modern[127] = "【降伏斷魔印】真言王說：「唵嚩多寸𮮍（一）　陀𮜈（二）　吽（三）」「令一切大惡魔等降伏的印：右手結大拳，當下意念所要降伏的對象。真言說：「唵惡惹（二合）佉吽」「令惡事惡相全部斷除燒盡的印：左右手指尖直立合併，對準心窩放在大指上方。【义解】本段給出大智印對應的真言，接著講降伏大惡魔印（右手大拳、觀想降伏對象）與真言；再講斷燒惡事印（指立合當心），用來消滅一切惡相。"
# 段128
modern[128] = "【壇場圓滿結界印】咒說：「唵誐賀尼吽發吒（引）」「接著作結界法印。左右手的水指、火指向內橫臥，左右手的地指指尖對合直立，左右手的風指如柱豎立分開，左右手大拇指並放，安放在壇中。真言說：「曩謨參漫多嚩娑囉（二合）難（一）　詮陀娜𫄅吽（二合引）【义解】本段給出斷燒惡事印的真言，隨後講最終圓滿結界印的詳細結法，安放在壇中，給出對應真言，至此護摩前的層層結界全部完成。"
# 段129
modern[129] = "【天王入三昧降魔】」那時多聞王想要利益眾生，還覺得力量不夠，不能降伏各種大惡魔神等，就進入阿娑波那伽三昧，這樣念道：「我沒有更大的力量降伏大惡魔了。」當即得到一切如來同力三昧智慧，成就降伏王體相。這個成就的體王，就得到一切如來金剛身、無礙智、一切智聚、無量福德藏、緊固法界王三昧。【义解】本段講本尊多聞王在降伏大魔前，入深三昧，得一切如來共同加持，成就金剛無礙智降伏法身，是本尊忿怒降魔的本源。"
# 段130
modern[130] = "【天王降伏體相莊嚴】這個就是以般若智為莊嚴的三昧，智慧火圍繞身體，以般若智慧力化作鐮刀持在手中，以般若為瓔珞、以智慧鏡為眼睛、以伏藏為座位。右邊踏著大惡魔鬼王作為座墊，以慈悲為體性身、以忿怒為面相、以降伏的觀想為手、以智慧火為頭髮相，以利益有情的心作為眉毛。【义解】本段詳細描述天王降伏忿怒身的莊嚴：般若為莊嚴、火繞身、般若鐮、般若瓔珞、智鏡眼、伏藏座、踏惡鬼王、慈悲體忿怒相、火髮、慈心眉，每一種相好都對應般若德相。"
# 段131
modern[131] = "【牙相與袈裟表法】三道水波形的頭髮，能燒盡一切眾生的災患、除去惡障，降伏無量惡魔鬼神等隨從事業，下方露出三寸長牙。為什麼牙是白色三寸長？因為歷經三世一切眾生的過去惡業、業障、災難、怖畏、生死輪迴，如果觀想這個牙，就給予眾生無量清淨身三昧。對於一切在佛法僧生惡事的惡人，以及放逸的沙彌、童男童女，全都能降伏；對於不持戒的比丘、比丘尼等也都能降伏，令所有不信的人降伏，全部歸依三寶。【义解】本段解釋天王頭髮水波相的作用（燒災除障降魔），以及三寸白牙的表法：淨除三世惡業，給予清淨三昧，降伏所有毀犯三寶、破戒、不信的人，令其歸依三寶。"
# 段132
modern[132] = "【身色衣色表法】就這樣以心作為兩足。袈裟是青色代表什麼相？代表一切眾生的各種大願都得滿足，也就是檀波羅蜜（布施）的相。青色的東西，最後一定會變成黃色。依這個觀想，又對應地輪的相。衣服是黑紺色，代表消除一切眾生的各種惡障礙、不祥，是風輪王的相。身體全部是赤色，代表令一切有情得明鏡、開智慧眼，又為一切眾生照明黑暗的事，都以這樣的相作為色相。【义解】本段解釋天王袈裟青色（布施波羅蜜、地輪、滿願）、內衣紺色（除障、風輪）、身色赤紅（開智慧眼、照明暗冥）的表法含義，令觀想時理解內在義理。"
# 段133
modern[133] = "【本尊持物表法】大天王的心以獅子迅疾的力量，和諸佛同心三昧。金剛心作為大王的意，一切眾生的善惡事業都能聽聞了知，這個觀想就是耳相。又諸佛如來的一切智慧般若智火，全都作為他的大火光相。以般若智心為寶塔，以般若道理為金剛鈴相，以各種甘味妙藥為甘露素，以種種滅除不淨、成就清淨的所依。【义解】本段解釋天王的意（金剛心，了知一切善惡，同諸佛三昧）、耳（聞一切善惡）、火光（般若智火）、左手寶塔（般若心）、金剛鈴（般若說法）、持藥（滅穢成淨）等持物與身相的表法。"
# 段134
modern[134] = "【十手表法續】把心觀想為箭相，以般若威光為弓相。以般若妙說的心髓為獨鈷，為了除滅一切眾生所作的惡事、誹謗佛法僧、一切眾生的罪業，令他們聽到諸佛授記的聲音。這個觀想就是金剛鈴相，為了辟除一切魔障惡事，令其無有餘剩。這個相就是金剛鉾相，以一乘教的利益為一面之想。【义解】本段繼續解釋十手持物的表法：箭（心）、弓（般若威光）、獨鈷（般若心髓，滅罪授記）、金剛鈴（說法覺悟）、金剛鉾（一乘教降魔），一一對應佛法的德用。"
# 段135
modern[135] = "【十二印功德】以四無量心為四大天王的體像，也就是王。以十二印作為大智藏的心眼，以這個印作為金剛身體。如果有行人受持這十二個印，現生就能得自在、得他心智，得無量自在身，首先要以般若心作為依據。接著是一面十手根本大火光降伏災難、無所不至的大陀羅尼說：【义解】本段總結：四無量心對應四大天王，十二印對應大智心眼，受持十二印現世得他心通、大自在，強調般若為根本；隨後引出一面十手本尊的根本大陀羅尼。"
